在 Electron 主进程中向渲染进程发送消息示例：
```js
// 主进程
win.webContents.send('channel-name', { msg: 'hello' });

// 渲染进程 (preload/renderer)
ipcRenderer.on('channel-name', (event, data) => {
  console.log(data);
});
```

In Electron, `ipcMain.on` handles asynchronous messages from renderer processes:

```javascript
// Main process
const { ipcMain } = require('electron');

ipcMain.on('asynchronous-message', (event, arg) => {
  console.log(arg); // "ping"
  event.reply('asynchronous-reply', 'pong');
});
```

```javascript
// Renderer process
const { ipcRenderer } = require('electron');

ipcRenderer.send('asynchronous-message', 'ping');
ipcRenderer.on('asynchronous-reply', (event, arg) => {
  console.log(arg); // "pong"
});
```

